41: func HandlePreInvocation(ctx context.Context, payload []byte, opts ...HookOption) ([]byte, error) {
42: 	var input PreInvocationPayload
43: 	if err := json.Unmarshal(payload, &input); err != nil {
44: 		return []byte("{}"), nil
45: 	}
46: 	input.Normalize()
47: 
48: 	if input.InvocationNum > 0 {
49: 		return []byte("{}"), nil
50: 	}
51: 	if os.Getenv("REPO_MEMORY_DISABLED") == "1" {
52: 		return []byte("{}"), nil
53: 	}
54: 	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" {
55: 		return []byte("{}"), nil
56: 	}
57: 
58: 	workspaceRoot := ""
59: 	if len(input.WorkspacePaths) > 0 {
60: 		workspaceRoot = input.WorkspacePaths[0]
61: 	} else {
62: 		workspaceRoot, _ = os.Getwd()
63: 	}
64: 	if workspaceRoot == "" {
65: 		return []byte("{}"), nil
66: 	}
67: 
68: 	if !config.IsEnrolledFast(workspaceRoot) {
69: 		return []byte("{}"), nil
70: 	}
71: 
72: 	repoID := ""
73: 	if entry, found, _ := config.FindRegistryEntry(config.DataDir(), workspaceRoot); found && entry != nil {
74: 		repoID = entry.RepoID
75: 	}
76: 	if repoID == "" {
77: 		cmd := exec.Command("git", "rev-parse", "--show-toplevel")
78: 		cmd.Dir = workspaceRoot
79: 		out, err := cmd.Output()
80: 		if err == nil {
81: 			repoID = filepath.Base(strings.TrimSpace(string(out)))
82: 		}
83: 	}
84: 	if repoID == "" {
85: 		return []byte("{}"), nil
86: 	}
87: 
88: 	idxPath := filepath.Join(config.DataDir(), repoID, "index.db")
89: 	idx, err := index.NewIndex(idxPath)
90: 	if err != nil {
91: 		return []byte("{}"), nil
92: 	}
93: 	defer idx.Close()
94: 
95: 	engine := delivery.NewEngine(idx, workspaceRoot)
96: 	ledger := delivery.NewLedger(input.ConversationID)
97: 
98: 	var injectSteps []InjectStep
99: 
100: 	// Task start moment
101: 	if input.InitialNumSteps <= 1 {
102: 		var promptTerms []string
103: 		for _, term := range strings.Fields(input.UserPrompt) {
104: 			if len(term) >= 3 {
105: 				promptTerms = append(promptTerms, term)
106: 			}
107: 		}
108: 
109: 		var diffPaths []string
110: 		cmd := exec.CommandContext(ctx, "git", "diff", "--name-only", "HEAD~1")
111: 		cmd.Dir = workspaceRoot
112: 		if out, err := cmd.Output(); err == nil {
113: 			lines := strings.Split(string(bytes.TrimSpace(out)), "\n")
114: 			for _, line := range lines {
115: 				if line != "" {
116: 					diffPaths = append(diffPaths, filepath.Join(workspaceRoot, line))
117: 				}
118: 			}
119: 		}
120: 
121: 		entries, err := engine.TaskStartEntries(ctx, promptTerms, diffPaths)
122: 		if err == nil && len(entries) > 0 {
123: 			formatted := delivery.FormatEntries(entries)
124: 			injectSteps = append(injectSteps, InjectStep{
125: 				SystemMessage: &SystemMessageEntry{
126: 					SystemMessage: formatted,
127: 					Metadata:      map[string]string{"moment": "task-start"},
128: 				},
129: 			})
130: 			for _, ent := range entries {
131: 				ledger.RecordInjection(delivery.InjectionRecord{
132: 					EntryID: ent.Entry.ID,
133: 					Channel: "systemMessage",
134: 					Moment:  delivery.MomentTaskStart,
135: 				})
136: 			}
137: 		}
138: 	}
139: 
140: 	// First-entry and first-touch moments
141: 	var touchedFiles []string
142: 	if input.TranscriptPath != "" {
143: 		steps, err := ParseTranscript(filepath.Dir(input.TranscriptPath))
144: 		if err == nil {
145: 			seenPaths := make(map[string]bool)
146: 			for _, step := range steps {
147: 				if len(step.ToolCalls) == 0 {
148: 					continue
149: 				}
150: 				var calls []map[string]any
151: 				if err := json.Unmarshal(step.ToolCalls, &calls); err != nil {
152: 					continue
153: 				}
154: 				for _, call := range calls {
155: 					fn, ok := call["function"].(map[string]any)
156: 					if !ok {
157: 						continue
158: 					}
159: 					argsStr, ok := fn["arguments"].(string)
160: 					if !ok || argsStr == "" {
161: 						continue
162: 					}
163: 					var args map[string]any
164: 					if err := json.Unmarshal([]byte(argsStr), &args); err != nil {
165: 						continue
166: 					}
167: 					for _, v := range args {
168: 						str, ok := v.(string)
169: 						if !ok {
170: 							continue
171: 						}
172: 						// If path is absolute and within workspace
173: 						if strings.HasPrefix(str, workspaceRoot) {
174: 							if !seenPaths[str] {
175: 								seenPaths[str] = true
176: 								touchedFiles = append(touchedFiles, str)
177: 							}
178: 						}
179: 					}
180: 				}
181: 			}
182: 		}
183: 	}
184: 
185: 	for _, path := range touchedFiles {
186: 		// Unique anchor
187: 		if !ledger.HasSeenAnchor(path) {
188: 			entries, err := engine.AnchorEntries(ctx, path)
189: 			if err == nil && len(entries) > 0 {
190: 				formatted := delivery.FormatEntries(entries)
191: 				injectSteps = append(injectSteps, InjectStep{
192: 					SystemMessage: &SystemMessageEntry{
193: 						SystemMessage: formatted,
194: 						Metadata:      map[string]string{"moment": "first-touch", "anchor": path},
195: 					},
196: 				})
197: 				for _, ent := range entries {
198: 					ledger.RecordInjection(delivery.InjectionRecord{
199: 						EntryID: ent.Entry.ID,
200: 						Channel: "systemMessage",
201: 						Moment:  delivery.MomentFirstTouch,
202: 					})
203: 				}
204: 			}
205: 			ledger.MarkAnchorSeen(path)
206: 		}
207: 	}
208: 
209: 	// Scopes
210: 	if len(touchedFiles) > 0 {
211: 		moduleScopes := config.DeriveModuleScopes(touchedFiles)
212: 		for _, mScope := range moduleScopes {
213: 			scopeName := mScope.Name
214: 			if !ledger.HasSeenDossier(scopeName) {
215: 				entries, err := engine.DossierEntries(ctx, scopeName)
216: 				if err == nil && len(entries) > 0 {
217: 					formatted := delivery.FormatEntries(entries)
218: 					injectSteps = append(injectSteps, InjectStep{
219: 						SystemMessage: &SystemMessageEntry{
220: 							SystemMessage: formatted,
221: 							Metadata:      map[string]string{"moment": "first-entry", "scope": scopeName},
222: 						},
223: 					})
224: 					for _, ent := range entries {
225: 						ledger.RecordInjection(delivery.InjectionRecord{
226: 							EntryID: ent.Entry.ID,
227: 							Channel: "systemMessage",
228: 							Moment:  delivery.MomentFirstEntry,
229: 						})
230: 					}
231: 				}
232: 				ledger.MarkDossierSeen(scopeName)
233: 			}
234: 		}
235: 	}
236: 
237: 	if len(injectSteps) == 0 {
238: 		return []byte("{}"), nil
239: 	}
240: 
241: 	resp := InjectStepsResponse{
242: 		InjectSteps: injectSteps,
243: 	}
244: 	out, err := json.Marshal(resp)
245: 	if err != nil {
246: 		return []byte("{}"), nil
247: 	}
248: 	return out, nil
249: }
